
-- ============================================================
-- 17. 祝福语库表 (greetings.json)
-- ============================================================
CREATE TABLE `hp_greetings` (
  `id`          INT UNSIGNED    NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `category`    VARCHAR(64)     NOT NULL COMMENT '分类（solar_terms/holidays/special_days/lunar_festivals）',
  `name`        VARCHAR(100)    NOT NULL COMMENT '名称（如：立春、元旦、情人节）',
  `content`     MEDIUMTEXT      NOT NULL COMMENT '祝福语内容（Markdown 格式）',
  `created_at`  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_category_name` (`category`, `name`),
  KEY `idx_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='祝福语库表';

-- 完整数据：24 节气 + 6 公历节日 + 7 农历节日 + 6 特殊日期 + 10 生日模板（源自 greetings.json）
-- 注：content 为 .cache/greetings.json 中的完整 Markdown 原文，schema 使用 MEDIUMTEXT 支撑。

-- 数据以 .cache/greetings.json 为准（自动同步）
