INSERT INTO `hp_greetings` (`category`, `name`, `content`) VALUES
  ('solar_terms', '雨水', '## 💧 雨水 - 春雨润物\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### 🌧️ 节气问候\n\n好雨知时节，当春乃发生！\n\n📅 **节气特点**\n   - 降雨增多，气温回升\n   - 春风化雨，万物萌动\n   - 适宜播种，春耕开始\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 多吃健脾祛湿食物\n     - 推荐：山药、薏米、红豆\n     - 少吃生冷油腻食物\n   \n   • **起居养生**\n     - 春捂秋冻，注意保暖\n     - 适度运动，增强体质\n     - 保持室内通风干燥\n   \n   • **健康提示**\n     - 预防倒春寒\n     - 注意防潮除湿\n     - 调理脾胃功能\n\n🌂 **出行提醒**\n   - 雨水渐多，出门带伞\n   - 注意添衣，预防感冒\n   - 路面湿滑，注意安全\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n💧 雨水时节，养生调理，\n   祝大家健康平安！') ,
  ('solar_terms', '惊蛰', '## 🐛 惊蛰 - 春雷始鸣\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### ⚡ 节气问候\n\n春雷惊百虫，万物生机盎然！\n\n📅 **节气特点**\n   - 春雷乃动，蛰虫惊起\n   - 气温回升，雨量增多\n   - 桃花初绽，柳丝泛绿\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 多吃清淡温补食物\n     - 推荐：梨、银耳、春笋\n     - 少吃辛辣刺激食物\n   \n   • **运动养生**\n     - 适宜户外运动\n     - 推荐：慢跑、太极、踏青\n     - 舒展筋骨，活血通络\n   \n   • **情志调养**\n     - 保持心情愉悦\n     - 避免急躁焦虑\n     - 顺应春阳之气\n\n⚠️ **健康提示**\n   - 预防春季传染病\n   - 注意增减衣物\n   - 多开窗通风\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n⚡ 惊蛰时节，万物复苏，\n   祝大家精神饱满，活力四射！') ,
  ('solar_terms', '春分', '## ☯️ 春分 - 昼夜平分\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### 🌓 节气问候\n\n春分者，阴阳相半也！\n昼夜平分，寒暑均衡！\n\n📅 **节气特点**\n   - 昼夜时间相等\n   - 气候温和适中\n   - 春意盎然，草长莺飞\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 保持饮食平衡\n     - 多吃时令蔬菜\n     - 推荐：菠菜、韭菜、豆芽\n   \n   • **起居养生**\n     - 作息规律，早睡早起\n     - 适度锻炼，增强免疫\n     - 保持心态平和\n   \n   • **情志调养**\n     - 调节情绪，保持平衡\n     - 避免大喜大悲\n     - 多亲近大自然\n\n🎯 **工作提示**\n   - 平衡工作与生活\n   - 劳逸结合，提高效率\n   - 保持良好状态\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n☯️ 春分时节，阴阳平衡，\n   祝大家身心健康，和谐美满！') ,
  ('solar_terms', '清明', '## 🌸 清明 - 清净明洁\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### 🌿 节气问候\n\n清明时节雨纷纷，\n万物生长，清净明洁！\n\n📅 **节气特点**\n   - 天清地明，气候清爽\n   - 春暖花开，草木繁茂\n   - 适宜踏青郊游\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 多吃养肝食物\n     - 推荐：枸杞、菊花茶\n     - 少食寒凉发物\n   \n   • **运动养生**\n     - 踏青郊游，放松心情\n     - 适度运动，舒展筋骨\n     - 接触自然，呼吸新鲜空气\n   \n   • **情志调养**\n     - 保持心情舒畅\n     - 缅怀先人，珍惜当下\n     - 调节情绪，避免悲伤过度\n\n⚠️ **健康提示**\n   - 注意防过敏\n   - 谨防春季感冒\n   - 适度增减衣物\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n🌸 清明时节，踏青养生，\n   祝大家健康平安！') ,
  ('solar_terms', '谷雨', '## 🌾 谷雨 - 雨生百谷\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### 🌧️ 节气问候\n\n谷雨时节，雨生百谷！\n春季最后一个节气，万物生长旺盛！\n\n📅 **节气特点**\n   - 雨量充沛，谷物生长\n   - 气温升高，春意渐浓\n   - 播种移苗，农事繁忙\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 健脾祛湿为主\n     - 推荐：薏米、红豆、茯苓\n     - 多喝谷雨茶，清火祛病\n   \n   • **起居养生**\n     - 早睡早起，顺应阳气\n     - 适度运动，避免大汗\n     - 注意防潮除湿\n   \n   • **情志调养**\n     - 保持心情愉悦\n     - 避免情绪波动\n     - 静心养性\n\n⚠️ **健康提示**\n   - 预防风湿病\n   - 注意皮肤护理\n   - 防止神经痛\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n🌾 谷雨时节，春末夏初，\n   祝大家身体健康，事业丰收！') ,
  ('solar_terms', '立夏', '## ☀️ 立夏 - 夏日初临\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### 🌞 节气问候\n\n立夏至，夏日始！\n万物繁茂，生机勃勃！\n\n📅 **节气特点**\n   - 夏季的开始\n   - 气温显著升高\n   - 雷雨增多，作物旺长\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 清淡饮食，少油腻\n     - 推荐：苦瓜、绿豆、冬瓜\n     - 多吃新鲜蔬果\n   \n   • **起居养生**\n     - 晚睡早起，午休养心\n     - 避免大汗淋漓\n     - 注意防暑降温\n   \n   • **养心为主**\n     - 立夏养心，保持平静\n     - 避免情绪激动\n     - 静心养性，修身养性\n\n💧 **健康提示**\n   - 多喝水，补充水分\n   - 防中暑，避免暴晒\n   - 清淡饮食，养护脾胃\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n☀️ 立夏时节，养心为要，\n   祝大家身心健康，清凉一夏！') ,
  ('solar_terms', '小满', '## 🌾 小满 - 物至小得盈满\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### 🌱 节气问候\n\n小满小满，江河渐满！\n麦粒渐满，夏熟作物饱满！\n\n📅 **节气特点**\n   - 夏熟作物籽粒渐满\n   - 降雨量增加\n   - 气温明显升高\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 清热祛湿为主\n     - 推荐：冬瓜、苦瓜、绿豆\n     - 少食辛辣油腻\n   \n   • **起居养生**\n     - 早起晚睡，保证午休\n     - 避免贪凉，适度纳凉\n     - 勤洗澡，保持清洁\n   \n   • **情志调养**\n     - 心平气和，戒躁戒怒\n     - 保持心情舒畅\n     - 避免情绪波动\n\n⚠️ **健康提示**\n   - 预防皮肤病\n   - 注意防潮除湿\n   - 避免过度贪凉\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n🌾 小满时节，清热祛湿，\n   祝大家身体健康，凉爽度夏！') ,
  ('solar_terms', '芒种', '## 🌾 芒种 - 麦熟梅黄\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### 🌾 节气问候\n\n芒种芒种，连收带种！\n麦熟梅黄，农事繁忙！\n\n📅 **节气特点**\n   - 有芒作物成熟收获\n   - 进入雨季，降水增多\n   - 气温高，湿度大\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 清淡饮食，健脾化湿\n     - 推荐：绿豆汤、酸梅汤\n     - 多吃杂粮，少食甜腻\n   \n   • **起居养生**\n     - 勤洗澡，勤换衣\n     - 保持室内通风干燥\n     - 午睡养神，恢复精力\n   \n   • **精神调养**\n     - 保持轻松愉快心情\n     - 听音乐、钓鱼等静心活动\n     - 避免烦躁易怒\n\n⚠️ **健康提示**\n   - 防暑防湿\n   - 预防肠胃疾病\n   - 注意食品卫生\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n🌾 芒种时节，防暑祛湿，\n   祝大家身体健康，清爽度夏！') ,
  ('solar_terms', '夏至', '## ☀️ 夏至 - 日长至此\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### 🌞 节气问候\n\n夏至日，昼最长！\n阳气最盛，阴气始生！\n\n📅 **节气特点**\n   - 全年白昼最长\n   - 气温最高时期\n   - 雷阵雨频繁\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 清淡为主，多吃苦味\n     - 推荐：苦瓜、莲子心\n     - 多喝水，补充盐分\n   \n   • **起居养生**\n     - 晚睡早起，午睡补眠\n     - 避免暴晒，防中暑\n     - 少开空调，适度纳凉\n   \n   • **养心护心**\n     - 夏至养心，清心寡欲\n     - 保持情绪平稳\n     - 避免过度劳累\n\n💧 **健康提示**\n   - 注意防暑降温\n   - 预防心脑血管疾病\n   - 合理使用空调\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n☀️ 夏至时节，养心为要，\n   祝大家健康平安，清凉度夏！') ,
  ('solar_terms', '小暑', '## 🌡️ 小暑 - 暑热渐盛\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### 🔥 节气问候\n\n小暑至，暑气升！\n梅雨结束，盛夏开始！\n\n📅 **节气特点**\n   - 天气炎热，尚未极热\n   - 雷暴频繁\n   - 作物快速生长\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 清热解暑为主\n     - 推荐：绿豆、西瓜、莲藕\n     - 少食辛辣油腻\n   \n   • **起居养生**\n     - 保证充足睡眠\n     - 避免长时间暴晒\n     - 适度运动，防中暑\n   \n   • **情志调养**\n     - 心静自然凉\n     - 保持心情平和\n     - 避免情绪激动\n\n⚠️ **健康提示**\n   - 防暑降温\n   - 预防空调病\n   - 注意饮食卫生\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n🌡️ 小暑时节，防暑为要，\n   祝大家健康清凉，平安度夏！') ,
  ('solar_terms', '大暑', '## 🔥 大暑 - 一年最热\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### ☀️ 节气问候\n\n大暑大暑，上蒸下煮！\n一年中最热的时期！\n\n📅 **节气特点**\n   - 气温最高\n   - 日照最强\n   - 雷雨最多\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 清热祛暑，养心健脾\n     - 推荐：绿豆汤、酸梅汤、西瓜\n     - 少食冷饮，避免贪凉\n   \n   • **起居养生**\n     - 避免长时间户外活动\n     - 保证充足睡眠和休息\n     - 合理使用空调\n   \n   • **运动养生**\n     - 选择早晚凉爽时段\n     - 避免剧烈运动\n     - 及时补充水分\n\n⚠️ **健康提示**\n   - 严防中暑\n   - 预防肠胃疾病\n   - 注意心脑血管健康\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n🔥 大暑时节，防暑第一，\n   祝大家平安度夏，身体健康！') ,
  ('solar_terms', '立秋', '## 🍂 立秋 - 秋日初至\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n### 🍁 节气问候\n\n立秋至，凉风起！\n秋季开始，暑去凉来！\n\n📅 **节气特点**\n   - 秋季的开始\n   - 气温逐渐下降\n   - 天高气爽，秋高气爽\n\n🌿 **养生建议**\n   • **饮食调养**\n     - 润燥养肺为主\n     - 推荐：梨、百合、银耳\n     - 少食辛辣，多食酸味\n   \n   • **起居养生**\n     - 早睡早起，养收敛之气\n     - 注意添衣，预防秋凉\n     - 保持室内湿度\n   \n   • **情志调养**\n     - 保持内心宁静\n     - 收敛神气，心平气和\n     - 避免悲秋情绪\n\n🎯 **贴秋膘**\n   - 适当进补，恢复体力\n   - 循序渐进，不可过量\n   - 注意荤素搭配\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n🍂 立秋时节，养肺润燥，\n   祝大家身体健康，神清气爽！') ,
